script:
class Component extends DCLogic {
state = { data: [], q: '', reveal: {}, selected: '', msg: '' };
mount() { this.refresh(); }
refresh(select) {
const api = parent.SONNA_API;
if (!api) return this.setState({ msg: 'Không kết nối được máy chủ.' });
api('GET', '/api/admin/orders').then((r) => {
if (r._status !== 200) return this.setState({ msg: r.error || 'Không tải được đơn hàng.' });
this.setState({ data: r.orders || [], selected: select || this.state.selected || ((r.orders || [])[0] || {}).code || '', msg: '' });
}).catch(() => this.setState({ msg: 'Lỗi kết nối máy chủ.' }));
}
update(status) {
const code = this.state.selected;
if (!code) return this.setState({ msg: 'Chưa có đơn hàng để cập nhật.' });
parent.SONNA_API('POST', '/api/admin/orders/' + encodeURIComponent(code), { status }).then((r) => {
if (r._status !== 200) return this.setState({ msg: r.error || 'Không cập nhật được đơn.' });
this.refresh(code);
}).catch(() => this.setState({ msg: 'Lỗi kết nối máy chủ.' }));
}
renderVals() {
const st = this.state, on = '#FF8A1F', off = '#A3ACC4', fmt = (n) => String(Number(n) || 0).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + '?';
const nav = [
{ label: 'Tổng quan', href: 'AdminDashboard.dc.html' }, { label: 'Quản lý acc', href: 'AdminAccounts.dc.html' },
{ label: 'Đơn hàng', href: 'AdminOrders.dc.html', active: true }, { label: 'Thanh toán', href: 'AdminPayments.dc.html' },
{ label: 'Người dùng', href: 'AdminUsers.dc.html' }, { label: 'Khuyến mãi', href: 'AdminPromos.dc.html' },
{ label: 'Nội dung website', href: 'AdminContent.dc.html' }, { label: 'Báo cáo', href: '#bao-cao' },
{ label: 'Phân quyền', href: 'AdminRoles.dc.html' }, { label: 'Nhật ký hoạt động', href: '#nhat-ky' }
].map((n) => ({ ...n, bg: n.active ? '#1F2538' : 'transparent', fg: n.active ? on : off }));
const list = st.data || [], current = list.find((o) => o.code === st.selected) || list[0];
const counts = { all: list.length, paid: list.filter((o) => o.status === 'Đã thanh toán').length, delivery: list.filter((o) => o.status === 'Đang bàn giao').length, done: list.filter((o) => o.status === 'Hoàn tất').length, refund: list.filter((o) => o.status === 'Đã hoàn tiền').length };
const tabs = [{ label: 'Tất cả', count: String(counts.all) }, { label: 'Đã thanh toán', count: String(counts.paid) }, { label: 'Đang bàn giao', count: String(counts.delivery) }, { label: 'Hoàn tất', count: String(counts.done) }, { label: 'Hoàn tiền', count: String(counts.refund) }].map((t, i) => ({ ...t, line: i === 0 ? on : 'transparent', fg: i === 0 ? '#EAEFFA' : off }));
const orders = list.map((o) => ({ id: o.code, user: o.username, acc: o.title, amount: fmt(o.total), status: o.status, col: o.status === 'Hoàn tất' ? '#43D9A0' : (o.status === 'Đã hoàn tiền' ? off : '#FFC24B'), time: o.time, bg: o.code === (current && current.code) ? '#1F2538' : 'transparent' }));
const query = (st.q || '').trim().toLowerCase();
const customerMap = new Map();
list.forEach((o) => { if (!customerMap.has(o.userId)) customerMap.set(o.userId, { name: o.username, contact: o.username, orders: [] }); customerMap.get(o.userId).orders.push(o); });
const found = Array.from(customerMap.values()).filter((u) => !query || u.name.toLowerCase().includes(query)).slice(0, 5);
const cs = { none: !!query && !found.length, list: found.length > 0, items: found.map((u) => ({ name: u.name, contact: u.contact, summary: u.orders.length + ' Đơn hàng', orders: u.orders.map((o) => ({ time: o.time, order: o.code, cat: o.title, sub: o.itemId, tk: ((o.accs || [])[0] || {}).line || '', mkShown: '????????', price: fmt(o.total), priceCol: on, status: o.status, statusCol: '#FFC24B', revealLabel: 'Hiện', toggle: () => this.setState({ selected: o.code }) })) })) };
const status = current ? current.status : 'Chưa có đơn';
const col = status === 'Hoàn tất' ? '#43D9A0' : (status === 'Đã hoàn tiền' ? off : '#FFC24B');
const firstAcc = current && (current.accs || [])[0];
const steps = [{ label: 'Tạo đơn', time: current ? current.time : '?', done: !!current }, { label: 'Thanh toán được xác nhận', time: current ? 'Thanh toán từ ví' : '?', done: !!current }, { label: 'Giao thông tin acc', time: status === 'Hoàn tất' ? 'Đã giao' : (status === 'Đã hoàn tiền' ? 'Đã hoàn tiền' : 'Đang chờ admin'), done: status === 'Hoàn tất' }, { label: 'Khách xác nhận hoàn tất', time: status === 'Hoàn tất' ? 'Đã xác nhận' : 'Chưa thực hiện', done: status === 'Hoàn tất' }, { label: 'Hết thời gian bảo hành', time: '?', done: false }].map((s) => ({ ...s, dot: s.done ? '#43D9A0' : '#2B3248', fg: s.done ? '#EAEFFA' : off }));
return { nav, tabs, orders, steps, cs, q: st.q, onQuery: (e) => this.setState({ q: e.target.value }), ordLabel: st.msg || status, ordCol: st.msg ? '#FF6B7A' : col, ordDone: status === 'Hoàn tất' || status === 'Đã hoàn tiền', onDeliver: () => this.update('Hoàn tất'), onRefund: () => { if (current && window.confirm('Hoàn tiền đơn ' + current.code + '?')) this.update('Đã hoàn tiền'); }, detail: current ? [{ k: 'Khách hàng', v: current.username }, { k: 'Đơn hàng', v: current.code }, { k: 'Sản phẩm', v: current.title }, { k: 'Tài khoản', v: firstAcc ? firstAcc.line.split('|')[0] : '?' }, { k: 'Số tiền', v: fmt(current.total) }, { k: 'Trạng thái', v: status }] : [{ k: 'Đơn hàng', v: 'Chưa có dữ liệu' }], msg: st.msg };
}
}
